    output = [[0]*n for _ in range(n)]

    blocks = [(1,3), (1,4), (2,3), (2,4), (5,1), (5,2), (6,1), (6,2)]

    # Corner cells for each block
    # Top-right block: (1,3), (1,4), (2,3), (2,4)
    # Bottom-left block: (5,1), (5,2), (6,1), (6,2)

    corner_sums = {4, 5, 6, 7, 8, 10}  # sums of cells on or near corners

    # Color rule: anti-diag through corner gets 3 if sum is odd, 6 if even,
    # but only on one side of block

    for r in range(n):
        for c in range(n):
            if (r, c) in blocks:
                output[r][c] = 2
                continue

            s = r + c
            if s in corner_sums:
                if s % 2 == 0:
                    output[r][c] = 6
                else:
                    output[r][c] = 3
            else:
                output[r][c] = 0

    print("V5:")
    for row in output:
        print(row)
    return output

